<?php

namespace DevForge\ApiDev\Services;

use Illuminate\Support\Str;

/**
 * Derives the model and table used to store an endpoint's data locally.
 *
 * Each top-level body field becomes a column; nested objects and arrays are
 * stored as JSON. The API response and its identifier are always stored.
 */
class StorageSchema
{
    /**
     * Marker placed in generated files so they can be told apart from hand-written ones.
     */
    public const string MARKER = 'Generated by the API Integration Builder.';

    /**
     * Columns the generated table always defines.
     *
     * @var list<string>
     */
    public const array RESERVED_COLUMNS = ['id', 'external_id', 'response', 'created_at', 'updated_at'];

    /**
     * Get the model class name for an endpoint, defaulting to integration + resource.
     *
     * For example, POST /v1/corporates on the Weavr integration becomes WeavrCorporate.
     *
     * @param  array<string, mixed>  $endpoint
     */
    public static function modelName(array $endpoint, string $integration): string
    {
        if (filled($endpoint['model'] ?? null)) {
            return Str::studly((string) $endpoint['model']);
        }

        $resource = collect(explode('/', (string) ($endpoint['path'] ?? '')))
            ->filter(fn (string $segment): bool => $segment !== '' && ! str_starts_with($segment, '{') && ! preg_match('/^v\d+$/i', $segment))
            ->last() ?? (string) ($endpoint['name'] ?? 'Record');

        return $integration.Str::singular(Str::studly((string) preg_replace('/[^A-Za-z0-9]+/', ' ', $resource)));
    }

    /**
     * Get the table name for a model.
     */
    public static function table(string $model): string
    {
        return Str::snake(Str::pluralStudly($model));
    }

    /**
     * Map top-level fields to table columns.
     *
     * @param  array<array-key, mixed>  $fields
     * @return list<array{column: string, field: string, method: string, arguments: list<int>, cast: string|null, doc: string}>
     */
    public function columns(array $fields): array
    {
        $columns = [];
        $seen = [];

        foreach ($fields as $field) {
            if (! is_array($field) || ! is_string($field['name'] ?? null)) {
                continue;
            }

            $column = Str::snake(str_replace('-', '_', $field['name']));

            if (in_array($column, self::RESERVED_COLUMNS, true)) {
                $column .= '_value';
            }

            if (in_array($column, $seen, true)) {
                continue;
            }

            $seen[] = $column;

            [$method, $arguments, $cast, $doc] = match ($field['type'] ?? 'string') {
                'integer' => ['bigInteger', [], 'integer', 'int|null'],
                'number' => ['decimal', [20, 6], null, 'string|null'],
                'boolean' => ['boolean', [], 'boolean', 'bool|null'],
                'date' => ['date', [], 'date', 'Carbon|null'],
                'datetime' => ['dateTime', [], 'datetime', 'Carbon|null'],
                'object', 'array' => ['json', [], 'array', 'array<mixed>|null'],
                'file' => ['string', [], null, 'string|null'],
                default => ['string', [], null, 'string|null'],
            };

            $columns[] = [
                'column' => $column,
                'field' => $field['name'],
                'method' => $method,
                'arguments' => $arguments,
                'cast' => $cast,
                'doc' => $doc,
            ];
        }

        return $columns;
    }
}
